import { ScaleQuantize } from 'd3-scale';
import React from 'react';

import { getLegendOrientation } from '../../../core/components/chart-layout/functions/orientation.js';
import { useChartLayoutOrientation } from '../../../core/components/chart-layout/hooks/useChartLayoutOrientation.js';
import { RangeLegend } from '../../../core/components/legend/range/RangeLegend.js';
import { RangeItem } from '../../../core/components/legend/range/types/range-legend.js';
import { buildLegendItemsFromRange } from '../../../core/functions/build-legend-items-from-range.js';
import { buildQuantizedRangeItems } from '../../../core/functions/build-quantized-range-items.js';
import { isValidColorPalette } from '../../../core/functions/is-valid-color-palette.js';
import { ColoredRange } from '../../../core/types/colored-range.js';
import {
  DEFAULT_FORMATTER,
  DEFAULT_HONEYCOMB_TILE_COLOR,
} from '../../constants.js';
import { useHoneycombBaseScale } from '../../hooks/use-honeycomb-base-scale.js';
import { useHoneycombColorScheme } from '../../hooks/use-honeycomb-color-scheme.context.js';

export const HoneycombRangeLegendRenderer = () => {
  const { orientation: layoutOrientation } = useChartLayoutOrientation();
  const colorScheme = useHoneycombColorScheme();
  const orientation = getLegendOrientation(layoutOrientation);
  const scale = useHoneycombBaseScale();
  let items: RangeItem[] = [];
  const invertItems = orientation === 'vertical';

  if (isValidColorPalette(colorScheme)) {
    items = buildQuantizedRangeItems(
      scale as ScaleQuantize<string>,
      invertItems,
    );
  } else {
    const range = colorScheme as ColoredRange[];
    invertItems && range.reverse();
    items = buildLegendItemsFromRange(range, DEFAULT_HONEYCOMB_TILE_COLOR);
  }

  return (
    <RangeLegend
      items={items}
      orientation={orientation}
      formatter={DEFAULT_FORMATTER}
    />
  );
};
